use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        // Items are marked seen only once the digest that considered them
        // has actually been published; an unpublished digest reached no reader.
        if published.published {
            for id in &published.considered {
                // Item ids are parser-computed digests; an empty id is never
                // a valid store key, so skip it rather than write it.
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
